CREATE TABLE IF NOT EXISTS vision14_teaching_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,source_id TEXT NOT NULL UNIQUE,summary_id INTEGER NOT NULL,object_key TEXT NOT NULL UNIQUE,file_size INTEGER NOT NULL DEFAULT 0,page_count INTEGER NOT NULL DEFAULT 0,coverage_percent INTEGER NOT NULL DEFAULT 0,rights_status TEXT NOT NULL,downstream_sale_allowed INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_id) REFERENCES vision14_sources(id) ON DELETE CASCADE,FOREIGN KEY(summary_id) REFERENCES vision14_book_summaries(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_v14_teaching_source ON vision14_teaching_documents(source_id,updated_at DESC);
